"""Les 29 combattants de la vague 6 (Matière n° 43 à 72 : lumière et ondes, chaleur et énergie,
atome et particules, unités et mesures).

Ajoutés au catalogue quand leurs 29 fiches sont prêtes : python3 outils/vague6/_integrer.py.
Même format que outils/vague5/_combattants.py ; « rare » : True pour un combattant Rare (110 PV, 54 Att, 4 Déf).
"""

PRISMES = ("atomie", "Le Phare des Prismes")
KELVINOR = ("atomie", "Les Fournaises de Kelvinor")
COLLISIONNEUR = ("atomie", "Le Collisionneur des Profondeurs")
ETALONS = ("atomie", "La Tour des Étalons")


def c(id, nom, style, familleStyle, specialite, famille, fiche, lieu, apparence, questions, histoire, liens, rare=False):
    return dict(id=id, nom=nom, style=style, familleStyle=familleStyle, rare=rare,
                specialite=specialite, famille=famille, domaine="Matière",
                fiche=fiche, generateur=None, difficulte=2, pays=lieu[0], lieu=lieu[1],
                apparence=apparence, questions=questions, histoire=histoire, liens=liens)


