assert len(COMBATTANTS) == 29
assert len({x["id"] for x in COMBATTANTS}) == 29
assert all(len(x["histoire"]) <= 420 for x in COMBATTANTS), [x["id"] for x in COMBATTANTS if len(x["histoire"]) > 420]
